import{_ as r,c as a,o as e,ak as o}from"./chunks/framework.14-H7uoj.js";const s="/img/png/408_CN/01.png",u=JSON.parse('{"title":"计算机网络的组成","titleTemplate":"408计算机网络","description":"综述","frontmatter":{"title":"计算机网络的组成","titleTemplate":"408计算机网络","description":"综述","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_CN/01/408_CN_2.md","filePath":"post/kaoyan/408/408_CN/01/408_CN_2.md","lastUpdated":1756268504000}'),n={name:"post/kaoyan/408/408_CN/01/408_CN_2.md"};function l(i,t,d,g,_,p){return e(),a("div",null,t[0]||(t[0]=[o('<h1 id="计算机网络的组成" tabindex="-1">计算机网络的组成 <a class="header-anchor" href="#计算机网络的组成" aria-label="Permalink to &quot;计算机网络的组成&quot;">​</a></h1><h2 id="从组成部分看" tabindex="-1">从组成部分看 <a class="header-anchor" href="#从组成部分看" aria-label="Permalink to &quot;从组成部分看&quot;">​</a></h2><p>从组成部分看，计算机网络主要由<strong>硬件</strong>、<strong>软件</strong>和<strong>协议</strong>三大部分组成。</p><ul><li><strong>硬件</strong>：主要由主机（也称端系统）、通信链路、交换设备和通信处理机（如网卡）等组成。</li><li><strong>软件</strong>：主要包括各种实现资源共享的软件和方便用户使用的各种工具软件。</li><li><strong>协议</strong>：计算机网络的核心，像交通规则一样，协议规定了网络传输数据时所遵循的规范。</li></ul><h2 id="从工作方式看" tabindex="-1">从工作方式看 <a class="header-anchor" href="#从工作方式看" aria-label="Permalink to &quot;从工作方式看&quot;">​</a></h2><p>从工作方式看，计算机网络可分为<strong>边缘部分</strong>和<strong>核心部分</strong>。</p><ul><li><strong>边缘部分</strong>：所有连接到互联网上的供用户直接使用的<strong>主机</strong>，用来进行通信和资源共享。</li><li><strong>核心部分</strong>：大量网络和连接这些网络的<strong>路由器</strong>，它为边缘部分提供连通性和交换服务。</li></ul><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+s+'" alt="HTML 初体验" width="450px" style="border-radius:10px;"></div><br><h2 id="从功能组成看" tabindex="-1">从功能组成看 <a class="header-anchor" href="#从功能组成看" aria-label="Permalink to &quot;从功能组成看&quot;">​</a></h2><p>从功能组成看，计算机网络由<strong>通信子网</strong>和<strong>资源子网</strong>组成。</p><ul><li><strong>通信子网</strong>：由各种传输介质、通信设备和相应的网络协议组成，它使网络具有数据传输、交换、控制和存储的能力，实现联网计算机之间的数据通信。</li><li><strong>资源子网</strong>：是实现资源共亨功能的设备及其软件的集合，向网络用户提供共享其他计算机上的硬件资源、软件资源和数据资源的服务。</li></ul>',13)]))}const h=r(n,[["render",l]]);export{u as __pageData,h as default};
